#!/usr/bin/env node
/**
 * 🐝 Swarm Orchestrator v3 — Optimized Multi-Agent Quality Control
 *
 * Optimizations in v3:
 *  - Parallel agent execution (Promise.all)
 *  - PerformanceAgent → checks Next.js render strategies, lazy loading
 *  - Enhanced complexity: nesting depth, import count, JSX complexity
 *  - Delta analysis: suppresses repeated warnings from previous runs
 *  - Improved filtering: excludes auto-generated dirs (.kimi, .knowledge, etc.)
 *  - Auto-fix suggestions in agent outputs
 *
 * 🐝 Swarm Orchestrator v2 — Real Multi-Agent Quality Control
 *
 * Runs actual local analysis across 5 swarm agents:
 *  - analyzer    → complexity, lint, AST heuristics
 *  - architect   → ADR compliance, import boundaries
 *  - tester      → test coverage, missing tests
 *  - security    → secrets, auth, RLS, trading safety
 *  - knowledge   → Honcho sync, session logging
 *
 * Usage:
 *   node scripts/swarm-orchestrator.mjs <task-type> [files...]
 *   node scripts/swarm-orchestrator.mjs review            # auto-diff
 *   node scripts/swarm-orchestrator.mjs security          # security-only review
 *   node scripts/swarm-orchestrator.mjs architect         # architecture-only review
 */

import { readFile, writeFile, mkdir, access } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { join, dirname, basename } from 'node:path';

const SWARM_DIR = '.kimi/swarm';
const KNOWLEDGE_DIR = '.knowledge';

const EXCLUDE_PATTERNS = [
  'node_modules/', '.next/', '.vercel/', 'package-lock.json',
  '.kimi/', '.knowledge/session/', '.lighthouseci/',
  'supabase/.temp/', '.changeset/',
  // Auto-generated data files
  /entities\.json$/,
  // Test coverage reports
  /coverage\//, /allure-(report|results)\//,
];

const C = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m'
};

function gitDiffFiles() {
  try {
    const out = execSync('git diff --name-status HEAD', { encoding: 'utf8', cwd: '/Users/taj/klarpakke' });
    return out.split('\n').map(s => s.trim()).filter(line => {
      if (!line) return false;
      const status = line.charAt(0);
      return status !== 'D'; // skip deleted files
    }).map(line => {
      // name-status format: "M\tpath" or "A\tpath" or "R100\told\tnew"
      const parts = line.split('\t');
      return parts.length >= 2 ? parts[parts.length - 1] : line;
    });
  } catch {
    return [];
  }
}

function gitStatusShort() {
  try {
    return execSync('git status --short', { encoding: 'utf8', cwd: '/Users/taj/klarpakke' }).trim();
  } catch {
    return '';
  }
}

async function fileExists(p) {
  try { await access(p); return true; } catch { return false; }
}

function complexityScore(content) {
  const lines = content.split('\n').length;
  const branches = (content.match(/\b(if|else|switch|case|for|while|catch|\?\:)\b/g) || []).length;
  const functions = (content.match(/\b(function|=>)\b/g) || []).length;
  // Nesting depth: count indentation levels
  const indentMatch = content.match(/^(\s*)\S/gm) || [];
  const maxNesting = indentMatch.reduce((max, line) => {
    const spaces = line.match(/^(\s*)/)?.[1]?.length || 0;
    return Math.max(max, Math.floor(spaces / 2));
  }, 0);
  // Import count
  const imports = (content.match(/^import\s+/gm) || []).length;
  // JSX complexity: count JSX tags
  const jsxTags = (content.match(/<[A-Z][a-zA-Z0-9_]*/g) || []).length;
  let score = Math.min(10,
    Math.ceil(lines / 80) +
    Math.ceil(branches / 8) +
    Math.ceil(functions / 10) +
    Math.ceil(maxNesting / 4) +
    Math.ceil(jsxTags / 15)
  );
  return { score, lines, branches, functions, maxNesting, imports, jsxTags };
}

class AnalyzerAgent {
  static async analyze(filePath, content) {
    const { score, lines, branches } = complexityScore(content);
    // Skip complexity checks for autogenerated data files and documentation
    const isDataFile = filePath.includes('.knowledge/session/') || (
      filePath.endsWith('.json') && (filePath.includes('entities') || filePath.includes('kg'))
    );
    const isDoc = filePath.endsWith('.md');
    // Page-level React components naturally have more JSX lines
    const isPageComponent = filePath.includes('/app/') && filePath.endsWith('.tsx');
    const lineThreshold = isPageComponent ? 700 : 500;
    if (isDataFile || isDoc) {
      return {
        complexity_score: 1,
        lines,
        risks: [],
        suggestions: [],
        approval: 'proceed'
      };
    }
    const risks = [];
    if (lines > lineThreshold) risks.push(`File exceeds ${lineThreshold} lines (${lines})`);
    if (score > 8) risks.push(`High complexity score (${score}/10)`);
    if (branches > 30) risks.push(`High branch count (${branches}) — consider splitting`);
    if (content.includes('any') && content.includes(':')) {
      const anyCount = (content.match(/\:\s*any\b/g) || []).length;
      if (anyCount > 2) risks.push(`Excessive use of 'any' (${anyCount})`);
    }
    const hasConsole = /\bconsole\.(log|warn|error)\b/.test(content);
    if (hasConsole && (filePath.includes('/lib/') || filePath.includes('/app/api/'))) {
      risks.push('Console statements in library/api code');
    }
    return {
      complexity_score: score,
      lines,
      risks,
      suggestions: lines > 400 ? ['Consider extracting sub-modules'] : [],
      approval: score > 9 || lines > 1000 ? (isPageComponent ? 'warn' : 'block') : score > 7 || lines > lineThreshold ? 'warn' : 'proceed'
    };
  }
}

class ArchitectAgent {
  static async analyze(filePath, content) {
    const violations = [];
    // Layer boundaries
    if (filePath.includes('/components/') && content.includes('from "@/lib/trading"')) {
      violations.push('Component imports directly from trading lib — use hooks or contexts');
    }
    if (filePath.includes('/lib/trading/') && content.includes('from "@/components/"')) {
      violations.push('Trading lib imports from components — violates layer boundary');
    }
    // Magic numbers outside constants
    if (filePath.includes('/lib/trading/') && !filePath.includes('constants.ts') && !filePath.includes('schemas.ts')) {
      const rawNumbers = (content.match(/\b\d+\.?\d*\b/g) || []).filter(n => parseFloat(n) > 1);
      if (rawNumbers.length > 5) {
        violations.push('Multiple raw numeric values — verify they are imported from constants.ts');
      }
    }
    // Missing types
    if (filePath.endsWith('.ts') && !filePath.endsWith('.d.ts') && !content.includes('interface') && !content.includes('type ')) {
      if (!filePath.includes('/app/') && !filePath.includes('layout.tsx') && !filePath.includes('page.tsx')) {
        violations.push('No type definitions found — consider adding explicit types');
      }
    }
    return {
      adr_compliance: ['KLA-91'],
      violations,
      boundary_check: violations.length > 0 ? 'fail' : 'pass',
      approval: violations.some(v => v.includes('violates')) ? 'block' : violations.length > 0 ? 'warn' : 'proceed'
    };
  }
}

class TesterAgent {
  static async analyze(filePath, content) {
    const isCritical = filePath.includes('/trading/') || filePath.includes('/auth/') || filePath.includes('/lib/');
    const testLevel = isCritical ? 'P0' : filePath.includes('/components/') || filePath.includes('/app/api/') ? 'P1' : 'P2';
    const scenarios = [];
    if (isCritical) scenarios.push('Happy path', 'Error handling', 'Edge cases', 'Security');
    else scenarios.push('Basic functionality');

    // Check for corresponding test file
    const dir = dirname(filePath);
    const base = basename(filePath).replace(/\.(ts|tsx|js|jsx)$/, '');
    const possibleTests = [
      `${dir}/${base}.test.ts`,
      `${dir}/${base}.test.tsx`,
      `${dir}/__tests__/${base}.test.ts`,
      `${dir}/__tests__/${base}.test.tsx`,
      `e2e/${base}.spec.ts`
    ];
    let hasTest = false;
    for (const t of possibleTests) {
      if (await fileExists(t)) { hasTest = true; break; }
    }
    if (!hasTest && isCritical) scenarios.push('MISSING: Add unit/integration test file');

    return {
      test_level: testLevel,
      scenarios,
      coverage_target: isCritical ? 90 : 80,
      has_test_file: hasTest,
      approval: (!hasTest && isCritical) ? 'add_tests' : 'proceed'
    };
  }
}

class SecurityAgent {
  static async analyze(filePath, content) {
    const findings = [];
    function add(sev, issue, mitigation) {
      findings.push({ severity: sev, file: filePath, issue, mitigation });
    }

    // Hardcoded secrets — skip autogenerated data files and refine regex
    const isDataFile = (
      filePath.endsWith('.json') && (filePath.includes('entities') || filePath.includes('kg'))
    );
    if (!isDataFile && !filePath.includes('.test.')) {
      // Match quoted strings of 20+ chars that look like secrets
      const secretMatches = (content.match(/['"][A-Za-z0-9_+/=]{20,}['"]/g) || []).filter(
        m => {
          const inner = m.slice(1, -1); // strip quotes
          // Exclude SQL identifiers (lowercase+underscore), API paths, known functions
          if (/^[a-z_]+$/.test(inner)) return false;           // SQL policy/table names
          if (!/[0-9]/.test(inner)) return false;               // No digits = likely identifier (camelCase, PascalCase, snake_case)
          if (inner.startsWith('/api/')) return false;          // API endpoint paths
          if (/gen_random_uuid|information_schema|pg_catalog|CURRENT_|NOW\(\)/i.test(m)) return false;
          return true;
        }
      );
      if (secretMatches.length > 0) {
        add('high', 'Possible hardcoded secret/token', 'Move to environment variables or Vault');
      }
    }
    // Auth callback hardcoding — skip markdown docs (file path mentions, not code)
    if (!filePath.endsWith('.md') && content.includes('/auth/callback') && !content.includes('getCallbackUrl')) {
      add('high', 'Hardcoded /auth/callback detected', 'Use getCallbackUrl() from @/lib/auth/config');
    }
    // Console logs in sensitive areas
    if (/\bconsole\.(log|warn|error)\b/.test(content) && (filePath.includes('/auth/') || filePath.includes('/trading/'))) {
      add('medium', 'Console logging in auth/trading code', 'Use structured logging or remove before production');
    }
    // SQL injection risk in raw SQL
    if (filePath.endsWith('.sql') || content.includes('execute_sql')) {
      if (content.includes('${') && content.includes('sql')) {
        add('high', 'Possible SQL interpolation', 'Use parameterized queries or RPC only');
      }
    }
    // RLS checks for migrations
    if (filePath.includes('migrations') && filePath.endsWith('.sql')) {
      if (!content.includes('ROW LEVEL SECURITY') && content.includes('CREATE TABLE')) {
        add('high', 'New table without RLS', 'Enable RLS and define policies');
      }
    }
    // Binance key handling
    if (filePath.includes('/trading/') && content.includes('apiKey') && !content.includes('Vault')) {
      add('medium', 'Binance key handling outside Vault pattern', 'Ensure keys are retrieved via get_binance_vault_keys()');
    }
    // Feature flag bypass for live trading
    if (filePath.includes('/trading/') && content.includes('live') && content.includes('order') && !content.includes('feature_flags')) {
      add('medium', 'Live trading logic without feature flag check', 'Verify live_trading_enabled flag is checked');
    }

    const blocks = findings.filter(f => f.severity === 'high').length;
    const warns = findings.filter(f => f.severity === 'medium').length;
    return {
      findings,
      checked: ['auth', 'api', 'db', 'trading', 'secrets'],
      approval: blocks > 0 ? 'block' : warns > 0 ? 'warn' : 'proceed'
    };
  }
}

class PerformanceAgent {
  static async analyze(filePath, content) {
    const findings = [];
    const fixes = [];
    // Check Next.js render strategy
    if (filePath.includes('/app/') && filePath.endsWith('.tsx')) {
      if (content.includes('export const dynamic = "force-dynamic"')) {
        findings.push('force-dynamic disables all caching — verify ISR is not better');
        if (content.includes('export const revalidate')) {
          findings.push('Conflicting: both force-dynamic AND revalidate defined');
        }
      }
      if (filePath.includes('/app/[locale]/page.tsx') && !content.includes('revalidate') && !content.includes('force-dynamic')) {
        findings.push('Landing page has no caching strategy — consider ISR');
        fixes.push('Add: export const revalidate = 60; // ISR with Sanity webhook invalidation');
      }
      // Check for below-fold optimization opportunities
      if (content.includes('import') && content.includes('from "next/dynamic"') && content.includes('ssr: true')) {
        const ssrTrueCount = (content.match(/ssr:\s*true/g) || []).length;
        if (ssrTrueCount >= 3) {
          findings.push(`${ssrTrueCount} dynamic imports use ssr:true — consider Client Component wrapper with ssr:false for below-fold`);
          fixes.push('Create a "use client" wrapper component that imports below-fold sections with ssr:false');
        }
      }
      // Check image optimization
      const imgWithoutPriority = (content.match(/<img\s/g) || []).length;
      const nextImgWithoutPriority = (content.match(/<Image\s(?!.*priority)/g) || []).length;
      if (nextImgWithoutPriority > 0 && filePath.includes('/app/')) {
        findings.push(`${nextImgWithoutPriority} <Image> without priority — LCP images should use priority`);
        fixes.push('Add priority prop to above-fold images: <Image src="..." priority ... />');
      }
    }
    // Check for Plausible script strategy
    if (content.includes('plausible.io') && !content.includes('strategy="lazyOnload"')) {
      findings.push('Plausible script without lazyOnload — blocks initial render');
      fixes.push('Add strategy="lazyOnload" to Plausible <Script> component');
    }
    return {
      findings,
      fixes,
      approval: findings.length > 0 ? 'warn' : 'proceed'
    };
  }
}

class KnowledgeAgent {
  static async analyze(filePath, content, taskType, results) {
    const timestamp = new Date().toISOString();
    const sessionDir = `${KNOWLEDGE_DIR}/session`;
    if (!existsSync(sessionDir)) {
      await mkdir(sessionDir, { recursive: true });
    }

    const anyBlocked = results.some(r => r.approval === 'block');
    const anyWarned = results.some(r => r.approval === 'warn' || r.approval === 'revise' || r.approval === 'add_tests');

    const entry = {
      timestamp,
      file: filePath,
      type: taskType,
      lines: content.split('\n').length,
      swarm_status: anyBlocked ? 'blocked' : anyWarned ? 'warned' : 'approved',
      agents: results.map(r => ({ agent: r.agent, approval: r.approval }))
    };

    const filename = `${timestamp.replace(/[:.]/g, '-')}-${basename(filePath).replace(/\./g, '-')}.json`;
    await writeFile(join(sessionDir, filename), JSON.stringify(entry, null, 2));

    return {
      files_created: [`session/${filename}`],
      patterns_identified: [],
      honcho_synced: false, // Sync happens once at workflow end
      wake_up_updated: false,
      approval: 'proceed'
    };
  }
}

class SwarmOrchestrator {
  constructor() {
    this.agents = {
      analyzer: AnalyzerAgent,
      architect: ArchitectAgent,
      tester: TesterAgent,
      security: SecurityAgent,
      performance: PerformanceAgent,
      knowledge: KnowledgeAgent
    };
  }

  async runWorkflow(workflowType, files) {
    console.log(`${C.magenta}`);
    console.log('╔══════════════════════════════════════════════════════════════════╗');
    console.log('║  🐝 KLARPAKKE SWARM v3 — Parallel Multi-Agent Quality Control   ║');
    console.log('╚══════════════════════════════════════════════════════════════════╝');
    console.log(`${C.reset}`);

    const workflows = {
      feature: ['analyzer', 'architect', 'tester', 'security', 'performance', 'knowledge'],
      bugfix: ['analyzer', 'tester', 'security', 'performance', 'knowledge'],
      refactor: ['analyzer', 'architect', 'tester', 'security', 'performance', 'knowledge'],
      security: ['security', 'analyzer', 'tester', 'knowledge'],
      review: ['analyzer', 'architect', 'tester', 'security', 'performance', 'knowledge'],
      architect: ['architect', 'analyzer', 'knowledge']
    };

    const agentOrder = workflows[workflowType] || workflows.review;
    const allResults = [];
    const fileResults = [];

    // Load previous report for delta analysis
    let prevReport = null;
    try {
      const prev = await readFile(`${KNOWLEDGE_DIR}/session/swarm-report-latest.json`, 'utf8');
      prevReport = JSON.parse(prev);
    } catch {
      // No previous report — first run
    }

    for (const file of files) {
      let content;
      try {
        content = await readFile(file, 'utf8');
      } catch (err) {
        console.log(`${C.red}❌ Cannot read ${file}: ${err.message}${C.reset}`);
        continue;
      }

      const fileReport = { file, agents: [] };

      // Run all agents in parallel (except knowledge which needs other results)
      const nonKnowledgeAgents = agentOrder.filter(a => a !== 'knowledge');
      const knowledgeAgent = agentOrder.find(a => a === 'knowledge');

      const agentPromises = nonKnowledgeAgents.map(async agentId => {
        const Agent = this.agents[agentId];
        try {
          const result = await Agent.analyze(file, content);
          return { agent: agentId, ...result };
        } catch (err) {
          return { agent: agentId, approval: 'block', error: err.message };
        }
      });

      const perFileResults = await Promise.all(agentPromises);

      // Knowledge agent runs last (needs other results)
      if (knowledgeAgent) {
        try {
          const kResult = await this.agents[knowledgeAgent].analyze(file, content, workflowType, perFileResults);
          perFileResults.push({ agent: knowledgeAgent, ...kResult });
        } catch (err) {
          perFileResults.push({ agent: knowledgeAgent, approval: 'block', error: err.message });
        }
      }

      // Delta analysis: filter warnings already seen in previous run for same file
      if (prevReport) {
        const prevFile = prevReport.results?.find(r => r.file === file);
        if (prevFile) {
          for (const result of perFileResults) {
            if (result.approval === 'warn') {
              const prevAgent = prevFile.agents.find(a => a.agent === result.agent);
              if (prevAgent && prevAgent.approval === 'warn') {
                // Check if warnings are identical
                const prevRisks = JSON.stringify(prevAgent.risks || prevAgent.violations || prevAgent.findings || []);
                const currRisks = JSON.stringify(result.risks || result.violations || result.findings || []);
                if (prevRisks === currRisks) {
                  result.approval = 'proceed';
                  result._suppressed = true;
                  result._suppressed_reason = 'Identical warning in previous run (delta analysis)';
                }
              }
            }
          }
        }
      }

      fileReport.agents.push(...perFileResults);
      allResults.push(...perFileResults);

      // Print results
      for (const result of perFileResults) {
        const status = result.approval === 'proceed' ? `${C.green}✅` :
                       result.approval === 'warn' || result.approval === 'add_tests' ? `${C.yellow}⚠️` :
                       `${C.red}❌`;
        const label = result.agent.charAt(0).toUpperCase() + result.agent.slice(1);
        const suppressed = result._suppressed ? ` ${C.cyan}(suppressed — seen before)${C.reset}` : '';
        console.log(`  ${status} ${label}: ${result.approval}${suppressed}${C.reset}`);
        if (result.findings?.length) {
          for (const f of result.findings) {
            const sevColor = f.severity === 'high' ? C.red : f.severity === 'medium' ? C.yellow : C.blue;
            console.log(`      ${sevColor}[${f.severity}]${C.reset} ${f.issue}`);
            if (f.mitigation) console.log(`      ${C.cyan}  → ${f.mitigation}${C.reset}`);
          }
        }
        if (result.violations?.length) {
          for (const v of result.violations) {
            console.log(`      ${C.yellow}!${C.reset} ${v}`);
          }
        }
        if (result.risks?.length) {
          for (const r of result.risks) {
            console.log(`      ${C.yellow}!${C.reset} ${r}`);
          }
        }
        if (result.scenarios?.length && !result.has_test_file) {
          console.log(`      ${C.blue}ℹ${C.reset} Missing tests — scenarios: ${result.scenarios.join(', ')}`);
        }
        if (result.fixes?.length) {
          for (const fix of result.fixes) {
            console.log(`      ${C.green}💡${C.reset} ${fix}`);
          }
        }
      }

      fileResults.push(fileReport);
      console.log('');
    }

    // Summary
    console.log(`${C.cyan}══════════════════════════════════════════════════════════════════${C.reset}`);
    const blocks = allResults.filter(r => r.approval === 'block').length;
    const warns = allResults.filter(r => r.approval === 'warn' || r.approval === 'revise' || r.approval === 'add_tests').length;
    const passes = allResults.filter(r => r.approval === 'proceed').length;

    const suppressed = allResults.filter(r => r._suppressed).length;
    console.log(`Results: ${C.green}${passes} passed${C.reset}, ${C.yellow}${warns} warnings${C.reset}, ${C.red}${blocks} blocked${C.reset}${suppressed > 0 ? ', ' + C.cyan + suppressed + ' suppressed (delta)' + C.reset : ''}`);

    // Write JSON report
    const reportPath = `${KNOWLEDGE_DIR}/session/swarm-report-latest.json`;
    await mkdir(`${KNOWLEDGE_DIR}/session`, { recursive: true });
    await writeFile(reportPath, JSON.stringify({
      workflow: workflowType,
      files,
      timestamp: new Date().toISOString(),
      summary: { passes, warns, blocks },
      results: fileResults
    }, null, 2));
    console.log(`${C.blue}📝 Report written to: ${reportPath}${C.reset}`);

    if (blocks > 0) {
      console.log(`${C.red}`);
      console.log('╔══════════════════════════════════════════════════════════════════╗');
      console.log('║  ⚠️  SWARM BLOCKED — Fix issues before proceeding               ║');
      console.log('╚══════════════════════════════════════════════════════════════════╝');
      console.log(`${C.reset}`);
      process.exit(1);
    }

    console.log(`${C.green}`);
    console.log('╔══════════════════════════════════════════════════════════════════╗');
    console.log('║  ✅ SWARM APPROVED — Proceed with confidence                    ║');
    console.log('╚══════════════════════════════════════════════════════════════════╝');
    console.log(`${C.reset}`);

    // Honcho sync via hermes CLI (MemPalace deprecated 2026-08-11)
    console.log(`${C.cyan}🧠 Synker til Honcho...${C.reset}`);
    try {
      execSync('hermes memory sync >/dev/null 2>&1 || true', {
        cwd: '/Users/taj/klarpakke',
        timeout: 15000
      });
      console.log(`${C.green}✅ Honcho sync complete${C.reset}`);
    } catch {
      console.log(`${C.yellow}⚠️  Honcho sync skipped (timeout or not configured)${C.reset}`);
    }
  }
}

async function main() {
  const [,, rawTaskType = 'review', ...explicitFiles] = process.argv;

  let taskType = rawTaskType;
  let files = explicitFiles.length > 0 ? explicitFiles : gitDiffFiles();

  if (files.length === 0) {
    const status = gitStatusShort();
    if (status) {
      console.log(`${C.yellow}No staged/uncommitted changes against HEAD.${C.reset}`);
      console.log('Git status:');
      console.log(status);
    } else {
      console.log('Usage: node swarm-orchestrator.mjs <task-type> [files...]');
      console.log('');
      console.log('Task types:');
      console.log('  review    - Full review of current git diff (default)');
      console.log('  feature   - New feature development');
      console.log('  bugfix    - Bug fix');
      console.log('  refactor  - Code refactoring');
      console.log('  security  - Security-focused review');
      console.log('  architect - Architecture-only review');
    }
    process.exit(1);
  }

  // Filter to code-relevant files
  const codeFiles = files.filter(f => {
    const hasCodeExt = f.match(/\.(ts|tsx|js|jsx|sql|json|yaml|yml|md)$/);
    const excluded = EXCLUDE_PATTERNS.some(pattern =>
      typeof pattern === 'string' ? f.includes(pattern) : pattern.test(f)
    );
    return hasCodeExt && !excluded;
  });

  if (codeFiles.length === 0) {
    console.log(`${C.yellow}No code files to review in the change set.${C.reset}`);
    process.exit(0);
  }

  const orchestrator = new SwarmOrchestrator();
  await orchestrator.runWorkflow(taskType, codeFiles);
}

main().catch(err => {
  console.error('Swarm error:', err);
  process.exit(1);
});
